function [xq,xqtilde,xqbar,xqhat] = qfactors_dke_yp(R0,Z0,XR,XZ,XBR,XBZ,XBphi);%% Calculation of the different q factors needed for solving the bounce averaged drift-kinetic-equation for% arbitrary equilibrium (see the notice for explanations concerning notations)%%   INPUT:%%       - Plasmae equilibrium parameters %%   OUTPUT:%   %       - xq (safety factor) [1,nr]%       - xqtilde [1,nr]%       - xqbar [1,nr]%       - xqhat [1,nr]%% by Yves Peysson <yves.peysson@cea.fr> (CEA/DRFC) and Joan Decker <jodecker@alum.mit.edu> (MIT/RLE)  %XR = XR';XZ = XZ';XBR = XBR';XBZ = XBZ';XBphi = XBphi';%[nt,np] = size(XR);%theta = linspace(0,2*pi,nt); % Angular gridXtheta = repmat(theta',[1,np]);%XBT = abs(XBphi); % Toroidal B-fieldXBP = sqrt(XBR.^2 + XBZ.^2); % Poloidal B-fieldXB = sqrt(XBT.^2 + XBP.^2); % Total B-field%% Half grid in theta for integration%XMBR = (XBR(1:nt-1,:) + XBR(2:nt,:))/2;XMBZ = (XBZ(1:nt-1,:) + XBZ(2:nt,:))/2;XMBphi = (XBphi(1:nt-1,:) + XBphi(2:nt,:))/2;XMB = sqrt(XMBR.^2 + XMBZ.^2 + XMBphi.^2);XMBmin = ones(nt-1,1)*min(XMB);%XMR = (XR(1:nt-1,:) + XR(2:nt,:))/2;XMZ = (XZ(1:nt-1,:) + XZ(2:nt,:))/2;%nm = nt - 1;%XMdt = diff(Xtheta);%%q (safety factor)%XMF = XMBphi.*((XMR - R0).^2 + (XMZ - Z0).^2)./abs(XMBR.*(XMZ - Z0) - XMBZ.*(XMR - R0))./XMR;xq = squeeze(sum(XMF.*XMdt))/(2*pi);%%qtilde%XMF = XMB.*((XMR - R0).^2 + (XMZ - Z0).^2)./abs(XMBR.*(XMZ - Z0) - XMBZ.*(XMR - R0))./R0;xqtilde = squeeze(sum(XMF.*XMdt))/(2*pi);%%qbar%XMF = XMBmin.*((XMR - R0).^2 + (XMZ - Z0).^2)./abs(XMBR.*(XMZ - Z0) - XMBZ.*(XMR - R0))./XMR;xqbar = squeeze(sum(XMF.*XMdt))/(2*pi);%%qhat %XMF = XMBmin.*((XMR - R0).^2 + (XMZ - Z0).^2)./abs(XMBR.*(XMZ - Z0) - XMBZ.*(XMR - R0))./R0;xqhat = squeeze(sum(XMF.*XMdt))/(2*pi);